import { useState, type ReactNode } from "react";

const TABS = [
  "Overview",
  "Control panel",
  "Metrics",
  "Console",
  "Files",
  "Snapshots",
  "Backups",
  "Networking",
  "Resize",
  "Activity",
] as const;

export function ServerTabs({
  initialTab,
  overview,
  controlPanel,
  metrics,
  console: consolePanel,
  files,
  snapshots,
  backups,
  networking,
  resize,
  activity,
}: {
  initialTab?: string;
  overview: ReactNode;
  controlPanel: ReactNode;
  metrics: ReactNode;
  console: ReactNode;
  files: ReactNode;
  snapshots: ReactNode;
  backups: ReactNode;
  networking: ReactNode;
  resize: ReactNode;
  activity: ReactNode;
}) {
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
  );

  const panels: Record<string, ReactNode> = {
    overview,
    "control panel": controlPanel,
    metrics,
    console: consolePanel,
    files,
    snapshots,
    backups,
    networking,
    resize,
    activity,
  };

  return (
