// ---------- 1. Scheduled backups ----------

/**
 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
 * first backup on its next pass.
 */
export async function setBackupSchedule(
  serverId: string,
  enabled: boolean,
  intervalHours: number
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
    return { error: "Choose a valid backup interval." };
  }

  await db.server.update({
    where: { id: server.id },
    data: {
      autoBackup: enabled,
      backupIntervalHours: enabled ? intervalHours : null,
    },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.backup_schedule",
      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

